mapper.select:
SELECT id, order_id, product_id, sku_id, sku_code, spec_json, product_name, image, sales_price, original_price, quantity, sub_total, discount_amount, insurance_detail, insurance_fee, after_sale_status, after_sale_id, is_deleted, created_at FROM order_items WHERE is_deleted = 0 AND order_id IN
#{orderId}
ORDER BY order_id ASC, id ASC
